 GEN_TAC THEN REWRITE_TAC[HT_WORD_SUB_SUB;SOME_FLAGS] THEN CONV_TAC NUM_REDUCE_CONV THEN (MATCH_MP_TAC SUBSUMED_FOR_SEQ THEN CONJ_TAC THENL [MAYCHANGE_IDEMPOT_TAC;CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC;(MATCH_MP_TAC SUBSUMED_FOR_SEQ THEN CONJ_TAC THENL [MAYCHANGE_IDEMPOT_TAC;CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC;(MATCH_MP_TAC SUBSUMED_FOR_SEQ THEN CONJ_TAC THENL [MAYCHANGE_IDEMPOT_TAC;CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC;(MATCH_MP_TAC SUBSUMED_FOR_SEQ THEN CONJ_TAC THENL [MAYCHANGE_IDEMPOT_TAC;CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC;(MATCH_MP_TAC SUBSUMED_FOR_SEQ THEN CONJ_TAC THENL [MAYCHANGE_IDEMPOT_TAC;CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC;(MATCH_MP_TAC SUBSUMED_FOR_SEQ THEN CONJ_TAC THENL [MAYCHANGE_IDEMPOT_TAC;CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC;(MATCH_MP_TAC SUBSUMED_FOR_SEQ THEN CONJ_TAC THENL [MAYCHANGE_IDEMPOT_TAC;CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC;(MATCH_MP_TAC SUBSUMED_FOR_SEQ THEN CONJ_TAC THENL [MAYCHANGE_IDEMPOT_TAC;CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC;(MATCH_MP_TAC SUBSUMED_FOR_SEQ THEN CONJ_TAC THENL [MAYCHANGE_IDEMPOT_TAC;CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC;(MATCH_MP_TAC SUBSUMED_FOR_SEQ THEN CONJ_TAC THENL [MAYCHANGE_IDEMPOT_TAC;CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC;(MATCH_MP_TAC SUBSUMED_FOR_SEQ THEN CONJ_TAC THENL [MAYCHANGE_IDEMPOT_TAC;CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC;(MATCH_MP_TAC SUBSUMED_FOR_SEQ THEN CONJ_TAC THENL [MAYCHANGE_IDEMPOT_TAC;CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC;SUBSUMED_MAYCHANGE_TAC]])]])]])]])]])]])]])]])]])]])]])]]));;
let C3_CLEANUP_FRAME_BYTE = prove
 (`!stackpointer addr:int64 s t:x86state. 48<=val stackpointer / ~c3_scratch stackpointer(val addr) / (MAYCHANGE [RIP;RSP;R13;RSI;RDI] ,, MAYCHANGE SOME_FLAGS ,, MAYCHANGE [memory :> bytes(word_sub stackpointer(word 48),48)] ,, MAYCHANGE [events]) s t
 ==> read memory t addr=read memory s addr`,
 REPEAT GEN_TAC THEN STRIP_TAC THEN
 SUBGOAL_THEN `nonoverlapping(addr:int64,1)(word_sub stackpointer(word 48),48)` ASSUME_TAC THENL
 [MATCH_MP_TAC C3_SCRATCH_BYTE_NONOVERLAPPING THEN ASM_REWRITE_TAC[];ALL_TAC] THEN
 SUBGOAL_THEN `read(memory :> bytes8(addr:int64))(t:x86state)=read(memory :> bytes8 addr)(s:x86state)` MP_TAC THENL
 [MATCH_MP_TAC(ISPECL[`memory :> bytes8(addr:int64)`;
 `[RIP;RSP;R13;RSI;RDI]:((x86state,int64)component)list`;
 `SOME_FLAGS:((x86state,bool)component)list`;
 `[memory :> bytes(word_sub(stackpointer:int64)(word 48),48)]`;
 `[events]:((x86state,uarch_event list)component)list`;`s:x86state`;`t:x86state`]R1_SECRET_FOUR_FRAME_PRESERVATION) THEN
 ASM_REWRITE_TAC[ALL] THEN REWRITE_TAC[SOME_FLAGS;ALL] THEN REPEAT CONJ_TAC THEN ORTHOGONAL_COMPONENTS_TAC;
 REWRITE_TAC[BYTES8_ELEMENT;READ_COMPONENT_COMPOSE;READ_ELEMENT]]);;
let C3_CLEANUP_FRAME_AC = prove
 (`!stackpointer:int64 s t:x86state.
 (MAYCHANGE [RIP;RSP;R13;RSI;RDI] ,, MAYCHANGE SOME_FLAGS ,, MAYCHANGE [memory :> bytes(word_sub stackpointer(word 48),48)] ,, MAYCHANGE [events]) s t
 ==> bit 18(read rflags t)=bit 18(read rflags s)`,
 REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[GSYM READ_BITELEMENT;GSYM READ_COMPONENT_COMPOSE] THEN
 MATCH_MP_TAC(ISPECL[`(rflags :> bitelement 18):(x86state,bool)component`;
 `[RIP;RSP;R13;RSI;RDI]:((x86state,int64)component)list`;
 `SOME_FLAGS:((x86state,bool)component)list`;
 `[memory :> bytes(word_sub(stackpointer:int64)(word 48),48)]`;
 `[events]:((x86state,uarch_event list)component)list`;`s:x86state`;`t:x86state`]R1_SECRET_FOUR_FRAME_PRESERVATION) THEN
 ASM_REWRITE_TAC[ALL] THEN REWRITE_TAC[SOME_FLAGS;ALL] THEN REPEAT CONJ_TAC THEN ORTHOGONAL_COMPONENTS_TAC);;
